package authz

import (
	"context"
	"encoding/json"
	"errors"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/internal/authz/db"
	"github.com/garamsh/garam/internal/errorx"
	"github.com/garamsh/garam/internal/grn"
)

// PostgresStore implements Store against PostgreSQL. The queries are
// generated by sqlc from queries.sql; append-only enforcement on
// policy_versions lives in the schema, not here.
type PostgresStore struct {
	pool *pgxpool.Pool
	q    *db.Queries
}

// Compile-time check that PostgresStore satisfies Store.
var _ Store = (*PostgresStore)(nil)

// NewPostgresStore constructs a Postgres-backed Store.
func NewPostgresStore(pool *pgxpool.Pool) *PostgresStore {
	return &PostgresStore{pool: pool, q: db.New(pool)}
}

// CreatePolicy stores the policy and its first version in one
// transaction, so a policy never exists without the version it points
// at.
func (s *PostgresStore) CreatePolicy(ctx context.Context, p *Policy, doc PolicyDocument, createdBy grn.GRN) (*Policy, error) {
	raw, err := json.Marshal(doc)
	if err != nil {
		return nil, errorx.Wrap(err, "authz store: encode policy document", errorx.KindInvalidArgument)
	}
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, errorx.Wrap(err, "authz store: begin", errorx.KindUnavailable)
	}
	defer func() { _ = tx.Rollback(ctx) }()

	q := s.q.WithTx(tx)
	row, err := q.CreatePolicy(ctx, db.CreatePolicyParams{
		Grn:            p.grn.String(),
		OrgGrn:         p.orgGRN.String(),
		Name:           p.name,
		Status:         string(p.status),
		DefaultVersion: int32(p.defaultVersion),
		CreatedAt:      stamp(p.createdAt),
		UpdatedAt:      stamp(p.updatedAt),
	})
	if err != nil {
		return nil, classify(err, "create policy", nil, ErrPolicyAlreadyExists)
	}
	if _, err := q.CreateFirstPolicyVersion(ctx, db.CreateFirstPolicyVersionParams{
		PolicyGrn: p.grn.String(),
		Document:  raw,
		CreatedBy: createdBy.String(),
		CreatedAt: stamp(p.createdAt),
	}); err != nil {
		return nil, classify(err, "create policy version", nil, nil)
	}
	if err := tx.Commit(ctx); err != nil {
		return nil, errorx.Wrap(err, "authz store: commit")
	}
	return rowToPolicy(row)
}

// GetPolicy returns the policy with the given GRN, or
// ErrPolicyNotFound.
func (s *PostgresStore) GetPolicy(ctx context.Context, g grn.GRN) (*Policy, error) {
	row, err := s.q.GetPolicy(ctx, g.String())
	if err != nil {
		return nil, classify(err, "get policy", ErrPolicyNotFound, nil)
	}
	return rowToPolicy(row)
}

// ListPolicies returns the org's policies ordered by GRN.
func (s *PostgresStore) ListPolicies(ctx context.Context, orgGRN grn.GRN) ([]*Policy, error) {
	rows, err := s.q.ListPolicies(ctx, orgGRN.String())
	if err != nil {
		return nil, classify(err, "list policies", nil, nil)
	}
	policies := make([]*Policy, 0, len(rows))
	for _, row := range rows {
		p, err := rowToPolicy(row)
		if err != nil {
			return nil, err
		}
		policies = append(policies, p)
	}
	return policies, nil
}

// AddPolicyVersion appends a version to an existing policy.
func (s *PostgresStore) AddPolicyVersion(ctx context.Context, g grn.GRN, doc PolicyDocument, createdBy grn.GRN) (*PolicyVersion, error) {
	raw, err := json.Marshal(doc)
	if err != nil {
		return nil, errorx.Wrap(err, "authz store: encode policy document", errorx.KindInvalidArgument)
	}
	row, err := s.q.AddPolicyVersion(ctx, db.AddPolicyVersionParams{
		PolicyGrn: g.String(),
		Document:  raw,
		CreatedBy: createdBy.String(),
		CreatedAt: stamp(time.Now().UTC()),
	})
	if err != nil {
		return nil, classify(err, "add policy version", ErrPolicyNotFound, nil)
	}
	return rowToPolicyVersion(row)
}

// ListPolicyVersions returns a policy's versions, oldest first.
func (s *PostgresStore) ListPolicyVersions(ctx context.Context, g grn.GRN) ([]*PolicyVersion, error) {
	rows, err := s.q.ListPolicyVersions(ctx, g.String())
	if err != nil {
		return nil, classify(err, "list policy versions", nil, nil)
	}
	versions := make([]*PolicyVersion, 0, len(rows))
	for _, row := range rows {
		v, err := rowToPolicyVersion(row)
		if err != nil {
			return nil, err
		}
		versions = append(versions, v)
	}
	return versions, nil
}

// SetPolicyStatus moves the policy through its lifecycle.
func (s *PostgresStore) SetPolicyStatus(ctx context.Context, g grn.GRN, status PolicyStatus) (*Policy, error) {
	row, err := s.q.SetPolicyStatus(ctx, db.SetPolicyStatusParams{
		Grn:       g.String(),
		Status:    string(status),
		UpdatedAt: stamp(time.Now().UTC()),
	})
	if err != nil {
		return nil, classify(err, "set policy status", ErrPolicyNotFound, nil)
	}
	return rowToPolicy(row)
}

// SetPolicyDefaultVersion points the policy at an already-stored
// version; rollback is exactly this pointer move (ADR-0002).
func (s *PostgresStore) SetPolicyDefaultVersion(ctx context.Context, g grn.GRN, version int) (*Policy, error) {
	if _, err := s.q.GetPolicyVersion(ctx, db.GetPolicyVersionParams{
		PolicyGrn: g.String(),
		Version:   int32(version),
	}); err != nil {
		return nil, classify(err, "get policy version", ErrPolicyVersionNotFound, nil)
	}
	row, err := s.q.SetPolicyDefaultVersion(ctx, db.SetPolicyDefaultVersionParams{
		Grn:            g.String(),
		DefaultVersion: int32(version),
		UpdatedAt:      stamp(time.Now().UTC()),
	})
	if err != nil {
		return nil, classify(err, "set policy default version", ErrPolicyNotFound, nil)
	}
	return rowToPolicy(row)
}

// AttachPolicy binds the policy to a subject. The schema rejects an
// attachment that leaves the policy's org.
func (s *PostgresStore) AttachPolicy(ctx context.Context, policyGRN, subjectGRN grn.GRN) (*PolicyAttachment, error) {
	row, err := s.q.AttachPolicy(ctx, db.AttachPolicyParams{
		PolicyGrn:  policyGRN.String(),
		SubjectGrn: subjectGRN.String(),
		CreatedAt:  stamp(time.Now().UTC()),
	})
	if err != nil {
		return nil, classify(err, "attach policy", ErrPolicyNotFound, ErrAttachmentAlreadyExists)
	}
	return rowToAttachment(row)
}

// DetachPolicy removes one attachment.
func (s *PostgresStore) DetachPolicy(ctx context.Context, policyGRN, subjectGRN grn.GRN) error {
	rows, err := s.q.DetachPolicy(ctx, db.DetachPolicyParams{
		PolicyGrn:  policyGRN.String(),
		SubjectGrn: subjectGRN.String(),
	})
	if err != nil {
		return classify(err, "detach policy", nil, nil)
	}
	if rows == 0 {
		return ErrAttachmentNotFound
	}
	return nil
}

// ListPolicyAttachments returns a policy's attachments ordered by
// subject GRN.
func (s *PostgresStore) ListPolicyAttachments(ctx context.Context, policyGRN grn.GRN) ([]*PolicyAttachment, error) {
	rows, err := s.q.ListPolicyAttachments(ctx, policyGRN.String())
	if err != nil {
		return nil, classify(err, "list policy attachments", nil, nil)
	}
	attachments := make([]*PolicyAttachment, 0, len(rows))
	for _, row := range rows {
		a, err := rowToAttachment(row)
		if err != nil {
			return nil, err
		}
		attachments = append(attachments, a)
	}
	return attachments, nil
}

// ActivePolicies returns what each active policy of the org evaluates
// at its default version, with the subjects it is attached to.
func (s *PostgresStore) ActivePolicies(ctx context.Context, orgGRN grn.GRN) ([]ActivePolicy, error) {
	rows, err := s.q.ActivePolicies(ctx, orgGRN.String())
	if err != nil {
		return nil, classify(err, "list active policies", nil, nil)
	}
	active := make([]ActivePolicy, 0, len(rows))
	for _, row := range rows {
		doc, err := ParsePolicyDocument(row.Document)
		if err != nil {
			return nil, errorx.Wrap(err, "authz store: stored document")
		}
		subjects := make([]grn.GRN, 0, len(row.SubjectGrns))
		for _, raw := range row.SubjectGrns {
			g, err := grn.Parse(raw)
			if err != nil {
				return nil, errorx.Wrap(err, "authz store: attachment subject grn")
			}
			subjects = append(subjects, g)
		}
		active = append(active, ActivePolicy{Document: doc, Subjects: subjects})
	}
	return active, nil
}

func rowToPolicy(row db.Policy) (*Policy, error) {
	g, err := grn.Parse(row.Grn)
	if err != nil {
		return nil, errorx.Wrap(err, "authz store: policy grn")
	}
	orgGRN, err := grn.Parse(row.OrgGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "authz store: policy org grn")
	}
	status, err := ParsePolicyStatus(row.Status)
	if err != nil {
		return nil, errorx.Wrap(err, "authz store: policy status")
	}
	return &Policy{
		grn:            g,
		orgGRN:         orgGRN,
		name:           row.Name,
		status:         status,
		defaultVersion: int(row.DefaultVersion),
		createdAt:      row.CreatedAt.Time,
		updatedAt:      row.UpdatedAt.Time,
	}, nil
}

func rowToPolicyVersion(row db.PolicyVersion) (*PolicyVersion, error) {
	g, err := grn.Parse(row.PolicyGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "authz store: policy grn")
	}
	createdBy, err := grn.Parse(row.CreatedBy)
	if err != nil {
		return nil, errorx.Wrap(err, "authz store: policy version author")
	}
	doc, err := ParsePolicyDocument(row.Document)
	if err != nil {
		return nil, errorx.Wrap(err, "authz store: stored document")
	}
	return &PolicyVersion{
		policyGRN: g,
		version:   int(row.Version),
		document:  doc,
		createdBy: createdBy,
		createdAt: row.CreatedAt.Time,
	}, nil
}

func rowToAttachment(row db.PolicyAttachment) (*PolicyAttachment, error) {
	policyGRN, err := grn.Parse(row.PolicyGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "authz store: policy grn")
	}
	subjectGRN, err := grn.Parse(row.SubjectGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "authz store: attachment subject grn")
	}
	return NewPolicyAttachment(policyGRN, subjectGRN, row.CreatedAt.Time), nil
}

// classify maps driver errors to errorx kinds. The append-only and
// same-org triggers raise a plain exception, which is a caller
// mistake, not an outage.
func classify(err error, op string, notFound, conflict error) error {
	if err == nil {
		return nil
	}
	if errors.Is(err, pgx.ErrNoRows) && notFound != nil {
		return notFound
	}
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) {
		switch pgErr.Code {
		case "23505":
			if conflict != nil {
				return conflict
			}
			return errorx.Wrap(err, "authz store: "+op, errorx.KindAlreadyExists)
		case "23503":
			if notFound != nil {
				return notFound
			}
			return errorx.Wrap(err, "authz store: "+op+": referenced row missing", errorx.KindNotFound)
		case "P0001":
			return errorx.Wrap(err, "authz store: "+op, errorx.KindFailedPrecondition)
		}
	}
	return errorx.Wrap(err, "authz store: "+op)
}

// stamp converts a time.Time to a valid pgtype.Timestamptz.
func stamp(t time.Time) pgtype.Timestamptz {
	return pgtype.Timestamptz{Time: t, Valid: true}
}
